import os
from typing import Callable, Optional

import azure.cognitiveservices.speech as speechsdk


def start_streaming_recognizer(
    language: str = "en-US",
    enable_punctuation: bool = True,
    audio_device: bool = True,
    audio_config: Optional[speechsdk.audio.AudioConfig] = None,
    on_recognized: Optional[Callable[[str], None]] = None,
    on_recognizing: Optional[Callable[[str], None]] = None,
    on_session_started: Optional[Callable[[], None]] = None,
    on_session_stopped: Optional[Callable[[], None]] = None,
    on_canceled: Optional[Callable[[str], None]] = None,
) -> speechsdk.SpeechRecognizer:
    speech_key = os.environ["AZURE_SPEECH_KEY"]
    speech_region = os.environ["AZURE_SPEECH_REGION"]

    speech_config = speechsdk.SpeechConfig(subscription=speech_key, region=speech_region)
    speech_config.speech_recognition_language = language
    speech_config.output_format = speechsdk.OutputFormat.Detailed

    if enable_punctuation:
        speech_config.set_property(
            speechsdk.PropertyId.SpeechServiceResponse_PostProcessingOption,
            "TrueText",
        )

    if audio_config is None:
        if not audio_device:
            raise ValueError("Provide audio_config when audio_device is False.")
        audio_config = speechsdk.audio.AudioConfig(use_default_microphone=True)

    recognizer = speechsdk.SpeechRecognizer(
        speech_config=speech_config,
        audio_config=audio_config,
    )

    def _recognized(evt: speechsdk.SpeechRecognitionEventArgs) -> None:
        if evt.result.reason == speechsdk.ResultReason.RecognizedSpeech:
            text = evt.result.text or ""
            if text and on_recognized:
                on_recognized(text)

    def _recognizing(evt: speechsdk.SpeechRecognitionEventArgs) -> None:
        if evt.result.reason == speechsdk.ResultReason.RecognizingSpeech:
            text = evt.result.text or ""
            if text and on_recognizing:
                on_recognizing(text)

    def _session_started(_: speechsdk.SessionEventArgs) -> None:
        if on_session_started:
            on_session_started()

    def _session_stopped(_: speechsdk.SessionEventArgs) -> None:
        if on_session_stopped:
            on_session_stopped()

    def _canceled(evt: speechsdk.SpeechRecognitionCanceledEventArgs) -> None:
        details = evt.result.cancellation_details
        message = f"{details.reason}"
        if details.error_details:
            message = f"{message}: {details.error_details}"
        if on_canceled:
            on_canceled(message)

    recognizer.recognized.connect(_recognized)
    recognizer.recognizing.connect(_recognizing)
    recognizer.session_started.connect(_session_started)
    recognizer.session_stopped.connect(_session_stopped)
    recognizer.canceled.connect(_canceled)

    recognizer.start_continuous_recognition()
    return recognizer
